import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BxGh02fV.js";const f=JSON.parse('{"title":"With an agent","description":"","frontmatter":{"title":"With an agent"},"headers":[],"relativePath":"en/agent/index.md","filePath":"en/agent/index.md"}'),s={name:"en/agent/index.md"};function n(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="with-an-agent" tabindex="-1">With an agent <a class="header-anchor" href="#with-an-agent" aria-label="Permalink to &quot;With an agent&quot;">​</a></h1><p>Your AI agent drives Effortless through its MCP verbs: it reads the project state, creates, updates, checks. You decide, the agent executes. The app shows the same project, at the same time: everything the agent does shows on screen (see the <a href="/Effortless/en/guide/">app guide</a>).</p><p>You talk to your agent in plain language. Each page of this guide starts from what you ask, then says what the agent does, what you get, and what happens when a call is refused.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>Effortless does not target one particular agent. Today, agents built on frontier models (LLMs) are the best placed to use it — Claude Code, Codex or Antigravity for example. Integration with opencode is in progress; depending on the model used, similar behavior is not guaranteed.</p><h2 id="working-at-your-best-the-agent-opened-at-the-project-root" tabindex="-1">Working at your best: the agent opened at the project root <a class="header-anchor" href="#working-at-your-best-the-agent-opened-at-the-project-root" aria-label="Permalink to &quot;Working at your best: the agent opened at the project root&quot;">​</a></h2><p>The best Effortless experience comes from a <strong>command-line agent</strong> — Claude Code, Codex or Antigravity, for example — whose session is opened <strong>at the project root</strong>, that is, in the folder that contains <code>effortless.json</code> and <code>.effortless/</code>.</p><p>Why the root:</p><ul><li>the Effortless MCP server recognizes the project from the folder where the session was opened. Opened anywhere else, it finds no project, and its verbs say so when they refuse;</li><li>the root is where <code>AGENTS.md</code> and <code>CLAUDE.md</code> live, which the agent reads at startup to learn the verbs and the method;</li><li>the agent works directly in the project&#39;s code, where its changes and commits go.</li></ul><p>In practice, in a terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projects/my-project</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the folder that contains effortless.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # or codex, or your agent&#39;s command</span></span></code></pre></div><p>Then talk to it: &quot;Where does the project stand?&quot; or &quot;Start a story for the quote form&quot;. Keep the Effortless app open alongside: you see, live, what the agent does.</p><p>Other ways of working remain comfortable:</p><ul><li><strong>the VS Code integrated terminal</strong> (or another editor&#39;s): open the project folder (<strong>File › Open Folder</strong>), then a new terminal — it already opens at the root. Run your agent there;</li><li><strong>your agent&#39;s extension or desktop client</strong>, as long as the session targets the project folder.</li></ul><p>If the agent answers that no Effortless project is found, the session was almost always not opened at the root: close it, move into the project folder, and start it again.</p><h2 id="connect-an-agent" tabindex="-1">Connect an agent <a class="header-anchor" href="#connect-an-agent" aria-label="Permalink to &quot;Connect an agent&quot;">​</a></h2><p>Two routes, which do the same job:</p><ul><li><strong>From the app</strong>: <strong>Preferences</strong>, <strong>MCP &amp; Skills</strong> category. Select the detected assistants, then <strong>Deploy</strong> (see <a href="/Effortless/en/guide/preferences.html">Profile and preferences</a>).</li><li><strong>Through the agent</strong>: <a href="/Effortless/en/reference/mcp/installation.html#deploy"><code>effortless_deploy</code></a>. With no parameter, it targets every client detected on the machine.</li></ul><p>Deployment installs:</p><ul><li>the Effortless MCP server configuration in each detected client;</li><li>a global Effortless guide, between markers, in the instruction files of the targeted agents (<code>~/.claude/CLAUDE.md</code>, <code>~/.config/opencode/AGENTS.md</code>): the rest of those files is left untouched;</li><li>for Claude Code, an Effortless status bar (<code>~/.claude/effortless/statusline.mjs</code>). If you already have your own status bar, it is kept: the deployment report gives you the line to set to adopt Effortless&#39;s.</li></ul><p>After a deployment, restart or reconnect the server in your agent so it sees the verbs.</p><h2 id="inside-a-project" tabindex="-1">Inside a project <a class="header-anchor" href="#inside-a-project" aria-label="Permalink to &quot;Inside a project&quot;">​</a></h2><p><a href="/Effortless/en/reference/mcp/installation.html#init"><code>effortless_init</code></a> and <a href="/Effortless/en/reference/mcp/pilotage.html#features"><code>effortless_features</code></a> (with <code>write_doc: true</code>) write two files at the project root, between markers, leaving the rest alone:</p><ul><li><code>AGENTS.md</code>: the full registry of verbs, derived from the engine. This is what the agent reads to know what to call.</li><li><code>CLAUDE.md</code>: it imports <code>AGENTS.md</code> (the <code>@AGENTS.md</code> line), for agents that read that file.</li></ul><p>Do not edit them between the markers: the section is regenerated.</p><h2 id="work-modes" tabindex="-1">Work modes <a class="header-anchor" href="#work-modes" aria-label="Permalink to &quot;Work modes&quot;">​</a></h2><p>The mode is set per project, in <strong>Project settings</strong> (<a href="/Effortless/en/guide/settings.html">see the screen</a>) or by asking the agent (<a href="/Effortless/en/reference/mcp/pilotage.html#mode-set"><code>effortless_mode_set</code></a>).</p><table tabindex="0"><thead><tr><th>Mode</th><th>What the agent may do</th></tr></thead><tbody><tr><td><strong>Full</strong></td><td>Moves forward autonomously, with no intermediate validation.</td></tr><tr><td><strong>Semi-auto</strong></td><td>Proposes, and you validate the key milestones. Execution tools are disabled: the team loop, running a release, public promotion. Moving the code into <code>codebase/&lt;stack&gt;/</code> does not run either.</td></tr><tr><td><strong>Tutored</strong></td><td>Pedagogical step by step: each step is explained and confirmed.</td></tr></tbody></table><h2 id="you-stay-in-control" tabindex="-1">You stay in control <a class="header-anchor" href="#you-stay-in-control" aria-label="Permalink to &quot;You stay in control&quot;">​</a></h2><p>Outgoing or irreversible actions (commit, push, tag, release, publication) are only done by the agent <strong>after your explicit agreement</strong>.</p><p>When a call is refused, the refusal says two things: a <code>code</code> (the cause) and an <code>act</code> (what to do so the same call succeeds: another verb, or an argument to fix). Your agent uses it directly; each journey page lists the real refusals of its verbs.</p><h2 id="the-journeys" tabindex="-1">The journeys <a class="header-anchor" href="#the-journeys" aria-label="Permalink to &quot;The journeys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>For</th></tr></thead><tbody><tr><td><a href="/Effortless/en/agent/demarrer.html">Get started</a></td><td>Create a project, take over an existing one, deploy.</td></tr><tr><td><a href="/Effortless/en/agent/faire-le-point.html">Take stock</a></td><td>Know where the project stands and what awaits you.</td></tr><tr><td><a href="/Effortless/en/agent/cadrer.html">Frame</a></td><td>Set decisions, questions and framing.</td></tr><tr><td><a href="/Effortless/en/agent/piloter.html">Steer</a></td><td>Epics, stories, tasks and phases.</td></tr><tr><td><a href="/Effortless/en/agent/evolutions.html">Evolutions</a></td><td>Note, order and graduate ideas.</td></tr><tr><td><a href="/Effortless/en/agent/normes.html">Standards</a></td><td>Development standards, shared source, amendments.</td></tr><tr><td><a href="/Effortless/en/agent/code.html">Code</a></td><td>Stacks, models, modules, drift.</td></tr><tr><td><a href="/Effortless/en/agent/qualite.html">Quality</a></td><td>Measure, validate, repair.</td></tr><tr><td><a href="/Effortless/en/agent/livrer.html">Deliver</a></td><td>Plan and run a release.</td></tr><tr><td><a href="/Effortless/en/agent/documentation.html">Documentation</a></td><td>Project documents, search, user documentation.</td></tr><tr><td><a href="/Effortless/en/agent/boucle-equipe.html">Team loop</a></td><td>Have analyst, developer and QA work in relay.</td></tr></tbody></table><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p>Every verb, its parameters and scope: <a href="/Effortless/en/reference/mcp/">MCP reference</a>.</p>`,35)])])}const g=t(s,[["render",n]]);export{f as __pageData,g as default};
